INSERT INTO "days" VALUES('2026-11-10','2026-11-10 00:12 → 2026-11-10 23:59（上海时间）','任务在这一天建立：先把跨工作区共享经验写成可审查的规格，再按“人做决定、Agent 做有界实验”做了主页 Agent Lab 的本地页。本地验证通过，但没有提交、没有 PR、没有上线。实验指标仍是未测量。','[{"repo": "本任务 · 经验闭环", "work": "写出跨工作区共享经验的规格、提示词、证据和审查。审查先发现两处阻塞：每日限额可能挡住结果收取，回退可能覆盖他人期间的修改。修订后文档复核无阻塞。", "status": "本地文档。只说明合同一致，不是系统已运行，也没有获批上线。", "evidence": "本地交付目录中的规格、提示词、证据、审查。原文未公开。"}, {"repo": "yhyu13.github.io 本地工作区", "work": "做了 Agent Lab 本地页：Craft 入口、菜单直达、决策记录、三个 milestone 计划和指标区。独立复核无阻塞，并修了大小写锚点。", "status": "未提交、未建 PR、未部署。模板 v0 未批准，自动发布未建立。三个 milestone 仍是计划，指标未测量。", "evidence": "本地 build 通过；schema/CLI 43 pass；浏览器 100 passed；首页 entry 294.52 kB，低于 300 kB 预算。"}]','2026-11-15T15:31:20+00:00','[{"repo": "yhyu13/DreamWeaverOPC1", "number": 210, "title": "[需人合并] docs(workflow): make human-agent delivery evidence reproducible (#209)", "state": "open", "url": "https://github.com/yhyu13/DreamWeaverOPC1/pull/210", "updated_at": "2026-11-10T15:22:19Z", "merged_at": null}, {"repo": "yhyu13/DreamWeaverOPC1", "number": 208, "title": "[需人合并] chore(assets): archive and remove Blender backups", "state": "merged", "url": "https://github.com/yhyu13/DreamWeaverOPC1/pull/208", "updated_at": "2026-11-10T13:52:05Z", "merged_at": "2026-11-10T13:52:02Z"}, {"repo": "yhyu13/DreamWeaverOPC1", "number": 207, "title": "[需人合并] docs(audit): complete original-goal audit and safe cleanup", "state": "merged", "url": "https://github.com/yhyu13/DreamWeaverOPC1/pull/207", "updated_at": "2026-11-10T13:19:59Z", "merged_at": "2026-11-10T13:19:57Z"}, {"repo": "yhyu13/AgentSkillsVault", "number": 21, "title": "feat(governance): add required checks and green/yellow/red task policy", "state": "merged", "url": "https://github.com/yhyu13/AgentSkillsVault/pull/21", "updated_at": "2026-11-10T09:01:49Z", "merged_at": "2026-11-10T09:01:49Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 190, "title": "feat(l3): 共同语言表与 /api/shared-language（同盟期的数据前提）", "state": "merged", "url": "https://github.com/yhyu13/PullYoursel