INSERT INTO "days" VALUES('2026-11-12','2026-11-12 00:00 → 2026-11-12 22:45（上海时间）','核对发现公开页仍停在 11 月 11 日的快照。按要求把任务从建立日到今天的记录补齐、脱敏，并重新发布。记忆库仍然只是本机命令行，这一轮没有做成 MCP 或 skill。','[{"repo": "yhyu13/agent-work-log", "work": "补上 11 月 10 日、11 日、12 日三条每日记录。每条包含总结、当日工作和当日 MR，并写明记录更新时间与每条 MR 的更新时间。", "status": "本次发布。个人主页仓库没有改，Agent Lab 仍未提交。", "evidence": "发布后以线上 latest.json 的 updatedAt、天数和 PR 数为准。"}, {"repo": "UnifiedAgentMemory", "work": "确认现有入口是本机 memory.py 的 search / inject。inject 只返回已批准经验，目前没有已批准条目。", "status": "没有新建 MCP，也没有新建 skill。", "evidence": "本机 CLI 与 sqlite。公开库仍是只读投影。"}]','2026-11-15T15:31:20+00:00','[{"repo": "yhyu13/yhyu13.github.io", "number": 25, "title": "feat(craft): host StudentSim and the wuxia demo as self-hosted works", "state": "merged", "url": "https://github.com/yhyu13/yhyu13.github.io/pull/25", "updated_at": "2026-11-12T15:10:04Z", "merged_at": "2026-11-12T15:10:04Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 195, "title": "docs(research): 竞品定位为 NOW 冥想 —— 官方事实 + 强制付费投诉证据", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/195", "updated_at": "2026-11-12T14:57:47Z", "merged_at": "2026-11-12T14:57:46Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 194, "title": "feat(005): 三问引导 + 每题回执 + 可验证承诺区", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/194", "updated_at": "2026-11-12T14:46:09Z", "merged_at": "2026-11-12T14:46:09Z"}, {"repo": "yhyu13/yhyu13.github.io", "number": 24, "title": "fix(decks): stop asserting a disputed guest name on the Huberman deck", "state": "merged", "url": "https://github.com/yhyu13/yhyu13.github.io/pull/24", "updated_at": "2026-11-12T14:39:02Z", "merged_at": "2026-11-12T14:39:02Z"}, {"repo": "yhyu13/AgentSkillsVault", "number": 30, "title": "feat(skills): multi-agent-repo-governance v1.2.0 — the seven gate self-blocking traps", "state": "merged", "url": "https://github.com/yhyu13/AgentSkillsVault/pull/30", "updated_at": "2026-11-12T14:38:47Z", "merged_at": "2026-11-12T14: