INSERT INTO "days" VALUES('2026-11-14','2026-11-14 00:00 → 本条记录更新时间（上海时间）','核对发现公开页仍停在 11 月 12 日。补上 13 日和 14 日，并刷新公开 PR 快照。记忆库仍然只是本机命令行。','[{"repo": "yhyu13/agent-work-log", "work": "补记 11 月 13 日无任务内更新，并刷新 PR 快照。每条 MR 只出现在它最近一次更新的那天。", "status": "本次发布。", "evidence": "发布后以线上 latest.json 的 updatedAt、天数和 PR 数为准。"}, {"repo": "UnifiedAgentMemory", "work": "记忆库可以做成 skill，也可以做成 MCP。Skill 规定何时查、只注入已批准经验；MCP 把 search 和 inject 变成工具。正本仍是本机库，不把公开网站当记忆来源。", "status": "这一轮只确认做法，没有新建 skill 或 MCP。", "evidence": "本机 memory.py 已有 search 和 inject。inject 在没有已批准经验时返回空。"}]','2026-11-15T15:31:20+00:00','[{"repo": "ailiaixue/pbl", "number": 289, "title": "feat(qa): 三端验收运行器与自动报告 (Refs #277)", "state": "merged", "url": "https://github.com/ailiaixue/pbl/pull/289", "updated_at": "2026-11-14T08:08:29Z", "merged_at": "2026-11-14T08:08:13Z"}, {"repo": "yhyu13/wuxia-town", "number": 109, "title": "feat(demo-shrink-span): 六面墙的残影分开收缩时长", "state": "open", "url": "https://github.com/yhyu13/wuxia-town/pull/109", "updated_at": "2026-11-14T07:33:59Z", "merged_at": null}, {"repo": "yhyu13/wuxia-town", "number": 108, "title": "feat(demo-hold-shrink): 残影停顿结束前先缩小", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/108", "updated_at": "2026-11-14T07:30:30Z", "merged_at": "2026-11-14T07:30:27Z"}, {"repo": "yhyu13/wuxia-town", "number": 107, "title": "feat(demo-hold-span): 六面墙的残影分开停顿时长", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/107", "updated_at": "2026-11-14T07:28:34Z", "merged_at": "2026-11-14T07:28:31Z"}, {"repo": "yhyu13/wuxia-town", "number": 106, "title": "feat(demo-trail-hold): 变浅完成的残影再停一短段", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/106", "updated_at": "2026-11-14T07:26:31Z", "merged_at": "2026-11-14T07:26:28Z"}, {"repo": "yhyu13/wuxia-town", "number": 105, "title": "feat(demo-trail-rate): 六面墙的残影分开变浅速度", "state": "merged", "url": "https://github.com/yhyu13/wuxia-town/pull/105", "updated_at": "2026-11-14T07:24:10Z", "merged_at": "2