INSERT INTO "days" VALUES('2026-11-15','2026-11-15 00:00 → 2026-11-15 23:30（上海时间）','这一天由定时任务在 23:30（上海时间）收口，没有新的人工对话。公开 PR 快照新增 19 条最近一次更新落在今天的条目；记忆库今天没有新写入，但上一版页面生成于 11 月 14 日 16:15，之后补记的 5 条候选经验会在这一版首次带出。','[{"repo": "yhyu13/agent-work-log", "work": "用公开 GitHub 搜索刷新 author:yhyu13 的 PR，区间是 2026-11-14T16:00:00Z 到 2026-11-15T15:59:59Z，返回 19 条且未标 incomplete；按链接并入快照后条目数从 220 涨到 239。同时补记当天记录并重建公开投影。", "status": "本次发布。个人主页仓库没有改，.github/workflows 没有提交。", "evidence": "发布后以线上 latest.json 的 updatedAt、天数和 PR 数为准。"}, {"repo": "UnifiedAgentMemory", "work": "记忆库今天没有新写入，最后修改停在 2026-11-14 16:54（上海时间），库里是 15 条候选经验。上一版公开页生成于 16:15，所以 11 月 14 日 16:28 之后补记的 5 条会在这一版首次出现：公开日更补记、MR 归日、skill 与 inject 的边界、inject 过期过滤、lessons 导出。", "status": "15 条全部是 candidate。这一轮没有批准任何经验，也没有新建 MCP 或 skill。", "evidence": "本机 sqlite 的 lessons 计数与状态分组；公开库条目数应与新版 latest.json 一致。"}]','2026-11-15T15:31:20+00:00','[{"repo": "ailiaixue/pbl", "number": 297, "title": "docs(weekly): 修订第二期周报 (Refs #291)", "state": "merged", "url": "https://github.com/ailiaixue/pbl/pull/297", "updated_at": "2026-11-15T15:07:36Z", "merged_at": "2026-11-15T15:07:35Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 254, "title": "feat(app): 作者卡加公众号二维码（在个人码下面，缺失降级）", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/254", "updated_at": "2026-11-15T14:36:33Z", "merged_at": "2026-11-15T14:36:33Z"}, {"repo": "yhyu13/AgentSkillsVault", "number": 45, "title": "feat(gate): 修 pycache 噪声 / 空 submodule 丢失 / 治理文档口径（red）", "state": "open", "url": "https://github.com/yhyu13/AgentSkillsVault/pull/45", "updated_at": "2026-11-15T14:33:06Z", "merged_at": null}, {"repo": "yhyu13/AgentSkillsVault", "number": 44, "title": "feat(scripts): 落地 skill lockfile / store 审计 / marketplace", "state": "open", "url": "https://github.com/yhyu13/AgentSkillsVault/pull/44", "updated_at": "2026-11-15T14:29:06Z", "merged_at": null}, {"repo": "ailiaixue/pbl", "number": 296, "title": "docs(weekly): 第二期周报 PDF (Refs #291)", "state": "merged", "url": "h