"yhyu13/PullYourselfUpApp", "number": 244, "title": "feat(llm+deploy): deepseek-flash 关思考 + test/dev 访问密钥门 + 生产→测试数据倒灌", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/244", "updated_at": "2026-11-15T08:27:00Z", "merged_at": "2026-11-15T08:27:00Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 240, "title": "fix(deploy): fail2ban jail 行尾注释导致服务 exit 255（安全防护实际未生效）", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/240", "updated_at": "2026-11-15T07:41:11Z", "merged_at": "2026-11-15T07:41:11Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 238, "title": "fix(deploy): root 读仓库要 safe.directory + 把 deploy key 交给服务用户", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/238", "updated_at": "2026-11-15T07:34:43Z", "merged_at": "2026-11-15T07:34:43Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 236, "title": "fix(deploy): useradd 把部署目录写满导致 clone 被静默跳过 + 克隆前预检仓库可达性", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/236", "updated_at": "2026-11-15T07:16:04Z", "merged_at": "2026-11-15T07:16:04Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 234, "title": "fix(deploy): .env 模板把 PORT 写成字面量，服务启动即 ERR_SOCKET_BAD_PORT", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/234", "updated_at": "2026-11-15T07:01:36Z", "merged_at": "2026-11-15T07:01:35Z"}, {"repo": "yhyu13/yhyu13.github.io", "number": 26, "title": "feat(identity): show the four personal photos and the official accoun…", "state": "merged", "url": "https://github.com/yhyu13/yhyu13.github.io/pull/26", "updated_at": "2026-11-15T06:58:15Z", "merged_at": "2026-11-15T06:58:15Z"}, {"repo": "yhyu13/PullYourselfUpApp", "number": 232, "title": "feat(deploy): setup/update 参数化支持同机三环境（prod/test/dev）+ 配置断言", "state": "merged", "url": "https://github.com/yhyu13/PullYourselfUpApp/pull/232", "updated_at": "2026-11-15T06:25:59Z", "merged_at": "2026-11-15T06:19:42Z"}]');
INSERT INTO "lessons" VALUES('M-0001','统一记忆库必须先于公开投影','cross-repo','先做 Agent Lab 公开页，但跨 repo 经验仍散在聊天/PR/deliverables，无法稳定回注下一轮。','个人 Agent 的核心基础设施是统一记忆库；公开页、周报、Decision Tree 都只能做脱敏投影。先建正本，再做展示。','多 repo、多会话、需要长期自我迭代时。','单次一次性任务不需要统一记忆库。','candidate','observed','conversation','2026-11-11 user correction: 我需要的就是一个统一的记忆库','memory,architecture,priority');
INSERT INTO "lessons" VALUES('M-0002','批准声明不等于真实授权','yhyu13.github.io','JSON 中 approved/autoPublish 字段可能被页面误读为本人已批准和发布系统可用。','批准元数据只能证明声明完整；真实授权必须来自本人消息或工具回执。页面不得把声明写成已批准或可自动发布。','公开记录、自动发布、规则采用。','无。','candidate','observed','code/test','AgentLabPage.tsx / agentLabSchema.mjs / agent-lab.spec.ts','approval,publication,safety');
INSERT INTO "lessons" VALUES('M-0003','实测指标必须有有限值、样本、方法和证据','cross-repo','未测量值可能被填 0，或非有限数/缺样本被包装成收益。','measured/estimated 必须有限数值、单位、方法、正整数样本量、证据引用；时间 ROI 必须有正分母。未测量/不可比保持 null。','ROI、实验结果、公开指标。','探索性笔记可写假设，但不能标 measured。','candidate','observed','code/test','agentLabSchema.mjs / check-agent-lab.test.mjs','metrics,roi,truth');
INSERT INTO "lessons" VALUES('M-0004','合并授权必须绑定实时 PR head','AgentSkillsVault','旧批准可能被新提交复用，导致未经重新审查的合并。','绿黄红分级和合并批准必须绑定当前 PR head、检查项和批准主体；head 变化即失效。','多 Agent PR、自动合并、治理模板。','只读调查不需要合并授权。','candidate','observed','commit/PR','AgentSkillsVault e791537 / PR #21','governance,pr,approval');
INSERT INTO "lessons" VALUES('M-0005','引用检查要分范围，避免误判断链','AgentSkillsVault','ref gate 把源仓路径、模板路径、SKILL.md 引用混在一起检查，产生误报。','check_refs.py 管 SKILL.md 契约引用；治理检查管 repo docs；模板用 glob 解析，不写死 tier 路径。','skill vault、模板仓、多目录引用。','单一简单 docs 仓可简化。','candidate','observed','commit','AgentSkillsVault 2c033bf / 6f48d96 / 626cd2a','refcheck,ci,skills');
INSERT INTO "lessons" VALUES('M-0006','测试服部署不等于生产上线','pbl','语音输入修复部署到测试服后，容易被误报为生产已更新。','汇报必须分开测试服/生产版本、head、worker 状态；生产未动就明确写未动。','多环境部署、用户验收。','无。','candidate','observed','task digest','AI_Turtor/pbl session 77fda2bf: test v1.7.22.92, prod v1.7.22.91','deployment,truth,pbl');
INSERT INTO "lessons" VALUES('M-0007','Pad/输入法问题要真机验收和前后证据','pbl','语音转写、输入法 composition、课堂布局容易发一版修一层。','Pad 类改动要求真机验收清单；issue 中补修复前后截图/录屏证据；独立对抗测试后再收尾。','移动端输入、课堂 UI、语音转写。','纯后端逻辑可用自动化测试为主。','candidate','observed','commit/PR/issue','pbl #266 / #278 / #279','mobile,acceptance,evidence');
INSERT INTO "lessons" VALUES('M-0008','CI 绿不等于可合并，独立审查可 BLOCKED','Aholo_Hackthon','PR CI 通过但来源所有权/历史引用/审查阻塞未解决。','独立审查必须能 BLOCKED；CI 只是必要条件。历史引用要区分历史快照和现行依据，来源所有权要登记。','比赛仓、文档退役、多 PR 审查。','无。','candidate','observed','commit/PR comment','Aholo_Hackthon spec-008 / PR #130 #131 #132 GRADE','review,ci,ownership');
INSERT INTO "lessons" VALUES('M-0009','研究产物先隔离，论文说法回原文核对','SimCity','AI 模拟/知识库研究可能污染 repo，或把二手说法当事实。','研究脚本和产物放临时目录；论文阈值/频率等回原文核对；未写入 repo 就不说 repo 已更新。','研究型任务、外部论文、沙盒复刻。','明确要入库的实现任务除外。','candidate','observed','task digest','SimCity session ccd15cfd: [temp dir] paper §4.2 threshold 150','research,isolation,truth');
INSERT INTO "lessons" VALUES('M-0010','大媒体长期走 Release，公开页走 lazy/budget/schema','yhyu13.github.io','MP4 进 Git 历史会撑大仓库；公开页可能增大首页入口或渲染坏数据。','同类视频多了改走 GitHub Release；公开页 lazy route、entry budget、运行时 schema、未知字段拒绝。','GitHub Pages、媒体资产、公开数据页。','小图标/短期演示可暂存 git。','candidate','observed','task digest/code','homepage PR #22 / Agent Lab build 294.52kB','pages,media,performance,schema');
INSERT INTO "lessons" VALUES('M-0011','公开日更不会自己续上','agent-work-log','11 月 12 日发布后，13 日没有新任务，14 日核对时页面仍停在 12 日的快照。','公开日更要显式补记。没有新工作也要写明当天无更新，并带上记录更新时间。上一天的快照不能代表之后的日子。','有按天发布的公开工作日志时。','一次性静态页不需要按日补记。','candidate','inferred','task','2026-11-12 至 2026-11-14 公开工作日志补记','log,freshness,publication');
INSERT INTO "lessons" VALUES('M-0012','同一条 MR 只记在最近一次更新日','agent-work-log','按 updated_at 重新归日后，10 日至 12 日的 MR 条数变少，容易看成记录丢失。','快照按最近一次更新归日时，一条 PR 只出现在最新那天。条数变化要说明是归日方式改变，不是工作被删。早于任务建立的条目只留在总表。','公开 PR 列表保存的是当前状态而不是每次更新的事件流水。','若保存的是事件流水，每次更新应各记一笔。','candidate','inferred','task','2026-11-14 PR 快照刷新','mr,snapshot,counting');
INSERT INTO "lessons" VALUES('M-0013','skill 只规定何时查，不保存记忆','cross-repo','让 Agent 使用记忆库时，容易把公开网站或 candidate 经验当成可注入规则。','本机 skill 只调用本机 inject。只使用 approved 或 adopted 且未过期的条目。公开网站是给人看的投影。没有已批准条目时返回空是正确结果，不能改去读网站或把 candidate 当规则。','Agent 需要在下一轮任务中回注跨 repo 经验时。','只读查看候选可以用 search，但查看结果不能注入。','candidate','inferred','task','2026-11-14 本机 unified-memory skill','skill,inject,boundary');
INSERT INTO "lessons" VALUES('M-0014','回注规则要由命令强制执行','UnifiedAgentMemory','说明里写了只用未过期经验，但 inject 原先不检查 expires_at。','Agent 实际调用的命令必须自己过滤状态和过期时间。改完后要用已批准未过期、已批准已过期、未批准三类样本验证，不能只改说明。','记忆回注有命令行或工具入口时。','纯给人阅读、没有命令声称已执行的笔记，可以只写规则。','candidate','inferred','code','2026-11-14 inject 过期过滤','inject,expiry,verification');
INSERT INTO "lessons" VALUES('M-0015','写入数据库后必须导出 lessons','UnifiedAgentMemory','数据库和程序改了，lessons 目录仍停在 11 月 11 日的初次导出。','lessons 和 index.md 不是正本，只在 export 时重写。add 写入成功后要自动导出。只改 memory.py 不会产生新的经验文件。','同时维护 sqlite 正本和 Markdown 导出时。','只有数据库、没有导出目录时不必导出。','candidate','inferred','task','2026-11-14 lessons 目录未更新','export,sqlite,lessons');
